请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-007

=== 用户原始指令 (query.txt) ===
给我弄个睡眠卡片嘛 一行带数字的话 点一下能跳转 能读天气 红色危险提示要有

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我弄个睡眠卡片嘛 一行带数字的话 点一下能跳转 能读天气 红色危险提示要有",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "sleep": {
        "summary": {
          "durationText": {
            "type": "string",
            "description": "睡眠时长数字展示文本。",
            "sampleValue": "7.2h"
          },
          "stageLabel": {
            "type": "string",
            "description": "当前睡眠阶段或质量短标签。",
            "sampleValue": "深睡"
          }
        }
      },
      "weather": {
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "alertLevel": {
            "type": "string",
            "description": "天气预警等级或危险提示文本。",
            "sampleValue": "红色预警"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠监督场景的彩色睡眠图标，适合用于睡眠卡片身份识别。"
    }
  ]
}

